action.command:
node -e "
const chunks = [];
process.stdin.on('data', d => chunks.push(d));
process.stdin.on('end', () => {
  const input = JSON.parse(Buffer.concat(chunks).toString());
  const prompt = (input.userMessage || '').toLowerCase();
  const addCommitMatch = prompt.match(/(?:add and commit|commit).*?['\"](.+?)['\"]/i) || prompt.match(/(?:add and commit|commit)\s+(?:with message\s+)?['\"]?(.+?)['\"]?\s*$/i);
  const isCommitRequest = /\b(add and commit|git commit|commit changes|commit everything)\b/.test(prompt);
  if (!isCommitRequest) {
    process.exit(0);
  }
  const message = addCommitMatch ? addCommitMatch[1] : 'Update changes';
  const { execSync } = require('child_process');
  try {
    const cwd = input.workspacePath || process.cwd();
    execSync('git add .', { cwd, stdio: 'inherit' });
    execSync('git commit -m \"' + message.replace(/\"/g, '\\\\\"') + '\"', { cwd, stdio: 'inherit' });
    console.log('Changes staged and committed with message: ' + message);
  } catch (e) {
    process.stderr.write('Git operation failed: ' + e.message);
    process.exit(1);
  }
});
"
